@PostMapping("/lawsuit/{lawsuitId}/revoke")
public Result revoke(@PathVariable String lawsuitId, @RequestBody RevokeRequest req) {
  String operatorId = req.getOperatorId(); // 自报，非鉴权上下文
  lawsuitService.revoke(lawsuitId, operatorId); // 未校验 operatorId 对 lawsuitId 的归属
  return Result.ok();
}

@PreAuthorize("@authz.ownsLawsuit(#lawsuitId, authentication)")
@PostMapping("/lawsuit/{lawsuitId}/revoke")
public Result revoke(@PathVariable String lawsuitId, @RequestBody RevokeRequest req) {
  lawsuitService.revoke(lawsuitId); // 归属已校验
  return Result.ok();
}
